using MoneyWeb.Data.Models;
using MoneyWeb.Data.Repositories.Interfaces;

namespace MoneyWeb.Data.Services;

public record BillSyncResult(int BillsChecked, int Added, int Removed)
{
    public bool Changed => Added > 0 || Removed > 0;
}

public interface IBillCashFlowSyncService
{
    /// <summary>Bring one bill's projected cash-flow entries in line with its schedule.</summary>
    Task<BillSyncResult> SyncAsync(Bill bill, int userId);

    /// <summary>Sync every bill the user has (inactive ones get their future auto-generated entries removed).</summary>
    Task<BillSyncResult> SyncAllAsync(int userId);
}

/// <summary>
/// Reconciles a bill's projected cash-flow entries against its schedule by diffing rather than
/// delete-and-regenerate, so nothing the user has acted on is lost:
/// - Expected: one entry per scheduled date from the period after the last recorded occurrence (never before
///   today) out to the horizon — only for active bills linked to a bank account.
/// - Removed: auto-generated entries (projected, not manual, not submitted) dated today or later that don't
///   match — wrong date, account, amount, name or auto-draft flag, a duplicate, or the bill is inactive/unlinked.
/// - Never touched: past-dated entries (pending items still to be cleared or skipped), submitted entries,
///   and manual overrides. A manual/submitted entry near a scheduled date counts as that date's payment
///   (it's usually the same payment moved by the user), so it isn't duplicated.
/// - Added: scheduled dates left with no entry.
/// </summary>
public class BillCashFlowSyncService(
    IBillRepository billRepo, ICashFlowRepository cfRepo, BillProjectionService projection) : IBillCashFlowSyncService
{
    private const int HorizonMonths = 12;

    public async Task<BillSyncResult> SyncAllAsync(int userId)
    {
        var bills = (await billRepo.GetAllAsync(userId, activeOnly: false)).ToList();
        int added = 0, removed = 0;
        foreach (var bill in bills)
        {
            var r = await SyncAsync(bill, userId);
            added += r.Added;
            removed += r.Removed;
        }
        return new BillSyncResult(bills.Count, added, removed);
    }

    public async Task<BillSyncResult> SyncAsync(Bill bill, int userId)
    {
        var today = DateOnly.FromDateTime(DateTime.Today);
        var isAutoDraft = bill.PaymentMethod == DebtPaymentMethod.AutoDraft;

        var startFrom = bill.NextFromAfterLastOccurrence(bill.LastOccurrenceDueDate, today);
        if (startFrom < today) startFrom = today;
        var expected = new List<DateOnly>();
        if (bill.IsActive && bill.BankAccountId.HasValue)
        {
            expected = projection.GetOccurrenceDates(bill, startFrom, today.AddMonths(HorizonMonths)).ToList();
        }
        var unclaimed = expected.ToHashSet();

        var existing = (await cfRepo.GetForSourceAsync(bill.Id, userId, TransactionCategory.Bill)).ToList();
        var removed = 0;

        // Auto-generated future entries: keep exact matches (first one per date), delete everything else.
        foreach (var t in existing.Where(t => IsAutoGenerated(t) && t.TransactionDate >= today))
        {
            var matches = t.BankAccountId == bill.BankAccountId
                          && t.Amount == -bill.Amount
                          && t.Description == Description(bill)
                          && t.IsAutoDraft == isAutoDraft
                          && unclaimed.Remove(t.TransactionDate);
            if (!matches)
            {
                await cfRepo.DeleteAsync(t.Id, userId);
                removed++;
            }
        }

        // Entries the user has acted on (manual or submitted) claim the nearest scheduled date within half a period.
        // Only ones in the projected range count — earlier ones belong to periods already recorded or past due.
        var tolerance = bill.Frequency switch
        {
            BillFrequency.Weekly   => 3,
            BillFrequency.BiWeekly => 7,
            _                      => 15
        };
        foreach (var t in existing.Where(t => !IsAutoGenerated(t) && t.TransactionDate >= startFrom))
        {
            var nearest = unclaimed
                .Where(d => Math.Abs(d.DayNumber - t.TransactionDate.DayNumber) <= tolerance)
                .OrderBy(d => Math.Abs(d.DayNumber - t.TransactionDate.DayNumber))
                .Cast<DateOnly?>()
                .FirstOrDefault();
            if (nearest.HasValue) unclaimed.Remove(nearest.Value);
        }

        var toAdd = unclaimed.OrderBy(d => d).Select(d => new CashFlowTransaction
        {
            UserId = userId,
            BankAccountId = bill.BankAccountId!.Value,
            TransactionDate = d,
            Description = Description(bill),
            Amount = -bill.Amount,
            Category = TransactionCategory.Bill,
            ReferenceId = bill.Id,
            IsProjected = true,
            IsAutoDraft = isAutoDraft
        }).ToList();
        if (toAdd.Count > 0)
            await cfRepo.BulkInsertProjectedAsync(toAdd);

        return new BillSyncResult(1, toAdd.Count, removed);
    }

    private static string Description(Bill bill) => $"Bill: {bill.Name}";

    private static bool IsAutoGenerated(CashFlowTransaction t) => t.IsProjected && !t.IsManualOverride && !t.IsSubmitted;
}
